var r=`0801-sosaties`;var s=`world-0801`;var t=`ZA`;var a=`southern-africa`;var n=4;var o=148;var l={en:`Sosaties`,ua:`Сосатіс`};var g={en:`Sosaties is a South Africa dish made with lamb, yellow onion, dried apricot, white vinegar. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сосатіс, страва кухні країни Південно-Африканська Республіка. Основні складники: ягнятина, жовта цибуля, курага, білий оцет. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Marinate the cubed lamb with curry, vinegar, onions and dried apricots for two hours in the refrigerator; the fruit provides sosaties’ characteristic sweet–sour flavor.`,ua:`Маринуйте кубики баранини з карі, оцтом, цибулею та курагою дві години в холодильнику: фрукти створюють характерний кисло-солодкий смак сосатіс.`,t:[`marinating`],m:120,i:[[`lamb`,680,`g`],[`yellow-onion`,160,`g`],[`dried-apricot`,100,`g`],[`curry-powder`,12,`g`],[`white-vinegar`,50,`ml`],[`brown-sugar`,25,`g`],[`table-salt`,null,`to_taste`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:12,i:[[`red-bell-pepper`,180,`g`]]},{en:`Grill over medium-high heat for about 14 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 14 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:14,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var u={slug:r,id:s,country:`ZA`,region:a,servings:4,minutes:148,title:l,text:g,steps:d};export{t as country,u as default,s as id,o as minutes,a as region,n as servings,r as slug,d as steps,g as text,l as title};